// GetUserByPATHash finds a user by PAT hash.
func (s *Store) GetUserByPATHash(ctx context.Context, tokenHash string) (*PATQueryResult, error) {
	result, err := s.driver.GetUserByPATHash(ctx, tokenHash)
	if err != nil {
		return nil, err
	}

	// Fetch user info
	user, err := s.GetUser(ctx, &FindUser{ID: &result.UserID})
	if err != nil {
		return nil, err
	}
	if user == nil {
		return nil, errors.New("user not found for PAT")
	}
	result.User = user

func isNumericUsername(username string) bool {
	if username == "" {
		return false
	}
	for _, char := range username {
		if char < '0' || char > '9' {
			return false
		}
	}
	return true
}

// ResolveUserByName resolves a username-based user resource name to a store user.
func ResolveUserByName(ctx context.Context, stores *store.Store, name string) (*store.User, error) {
	username, err := parseUsernameFromName(name)
	if err != nil {
		return nil, err
	}
	user, err := stores.GetUser(ctx, &store.FindUser{Username: &username})
	if err != nil {
		return nil, errors.Wrap(err, "resolve user by name: GetUser failed")
	}
	return user, nil
}
